 INSERT INTO public.performance_protocols(protocol_id,name,purpose,published,content_kind,authoring_scope,endorsement_status,organisation_id,session_lineage_id,revision_number,lifecycle_status,duration_min,primary_session_intent,coaching_notes) VALUES
  ('APOLLO-W7-MON-R1','Apollo Strength','Phase II overload upper-body strength plus Apollo-priority hypertrophy.','false','session','organisation','organisation_approved','apollo-dogfood','a1700001-0000-4000-8000-000000000001',1,'draft',100,'upper_body_strength','Later pull-up and bench sets may approach 1 RIR; no compound failure; conservative neck work.'),
