INSERT INTO public.session_blocks(block_id,session_id,block_type,title,content,workout_format,timer_config,coach_notes,position) VALUES
 ('b1700001-0000-4000-8000-000000000001','APOLLO-W7-MON-R1','warm_up','Apollo Shoulder Balance Warm-Up','Thoracic extension over foam roller: 5 slow reps at 2-3 positions; Open-book rotation: 6/side; Serratus wall slide + reach: 2x8; Wall Y/lower-trap raise: 2x8-10 very light; Single-arm cable/band row with reach: 2x10/side; then 2-4 progressive sets for first compound.','none',NULL,'Do not cue permanent shoulders down and back.',1),
 ('b1700002-0000-4000-8000-000000000002','APOLLO-W7-MON-R1','strength','Phase II overload strength','No compound failure; conservative neck work only.','none',NULL,NULL,2),
 ('b1700003-0000-4000-8000-000000000003','APOLLO-W7-TUE-R1','warm_up','Run preparation','5 minutes brisk walk/easy jog before Zone 2.','none',NULL,NULL,1),
 ('b1700004-0000-4000-8000-000000000004','APOLLO-W7-TUE-R1','conditioning','Zone 2 run','65 minutes conversational Zone 2 at RPE 3-4; do not extend duration.','intervals','{"work_seconds":3900,"tracking":["distance","average_pace","average_hr"],"intensity":"zone_2"}'::jsonb,'Track distance, average pace and average HR.',2),
 ('b1700005-0000-4000-8000-000000000005','APOLLO-W7-TUE-R1','core','Hanging Leg Raise','3 x 8-12; rest 60-90 seconds.','none',NULL,NULL,3),
 ('b1700006-0000-4000-8000-000000000006','APOLLO-W7-TUE-R1','cool_down','Full Apollo mobility flow','Knee-to-wall ankle rocks 2x8/side; 90/90 hip switches 2x8/side; adductor rock-back 2x8/side; half-kneeling hip-flexor stretch with reach 45 sec/side; deep-squat pry 2x30 sec; open-book rotation 6/side; wall slide with reach 2x8; passive hang 2x30 sec.','none',NULL,NULL,4),
 ('b1700007-0000-4000-8000-000000000007','APOLLO-W7-WED-R1','warm_up','Lower-body warm-up','Easy cardio 5 min; knee-to-wall ankle rocks 8/side; 90/90 hip switches 8/side; adductor rock-backs 8/side; glute bridge 2x10; bodyweight squat 2x8; progressive squat and RDL warm-up sets.','none',NULL,NULL,1),
 ('b1700008-0000-4000-8000-000000000008','APOLLO-W7-WED-R1','strength','Racehorse strength','All unilateral prescriptions are per leg; carries are heavy; no grinders.','none',NULL,NULL,2),
 ('b1700009-0000-4000-8000-000000000009','APOLLO-W7-THU-R1','warm_up','Interval warm-up','12-minute easy jog; leg swings 10/side; A-skips 2x20m; 3x20-second strides.','none',NULL,NULL,1),
 ('b1700010-0000-4000-8000-000000000010','APOLLO-W7-THU-R1','conditioning','Hard intervals','7 x 3 minutes hard at RPE 8.5-9; 90-second easy-jog recoveries; 21 total hard minutes.','intervals','{"rounds":7,"work_seconds":180,"recovery_seconds":90,"tracking":["interval_pace"],"effort":"hard","rpe":"8.5-9","total_quality_seconds":1260}'::jsonb,'Record every interval pace.',2),
 ('b1700011-0000-4000-8000-000000000011','APOLLO-W7-THU-R1','cool_down','Easy-jog cooldown','10 minutes easy jogging.','none','{"work_seconds":600}'::jsonb,NULL,3),
 ('b1700012-0000-4000-8000-000000000012','APOLLO-W7-FRI-R1','warm_up','Apollo Shoulder Balance Warm-Up','Thoracic extension over foam roller: 5 slow reps at 2-3 positions; Open-book rotation: 6/side; Serratus wall slide + reach: 2x8; Wall Y/lower-trap raise: 2x8-10 very light; Single-arm cable/band row with reach: 2x10/side; then 2-4 progressive sets for first compound.','none',NULL,NULL,1),
 ('b1700013-0000-4000-8000-000000000013','APOLLO-W7-FRI-R1','strength','Apollo Sculpt','Ten prescriptions, including controlled neck work.','none',NULL,'Isolation rest 60-90 seconds; neck rest 45-60 seconds.',2),
 ('b1700014-0000-4000-8000-000000000014','APOLLO-W7-SAT-R1','warm_up','Athletic warm-up','Easy cardio 5 min; ankle pogos 2x20; World''s greatest stretch 5/side; glute bridge 10; jump landing rehearsal 2x3; progressive trap-bar warm-up sets.','none',NULL,NULL,1),
 ('b1700015-0000-4000-8000-000000000015','APOLLO-W7-SAT-R1','strength','Strength and power','Rotational throws and box jumps use full recovery; trap-bar deadlift has explosive intent.','none',NULL,NULL,2),
 ('b1700016-0000-4000-8000-000000000016','APOLLO-W7-SAT-R1','conditioning','Four-round sled/SkiErg circuit','Four rounds: Sled Push 20 m; Sled Pull 20 m; SkiErg 250 m; Burpees 8; rest 90 seconds between rounds.','rounds','{"rounds":4,"between_round_recovery_seconds":90,"target_rpe":"7-8","execution_group_key":"apollo_w7_sat_conditioning","round_sequence":["EX-131","EX-132","EX-050","EX-009"],"progression":"improve_load_pace_or_transitions_not_rounds"}'::jsonb,'Complete the authored order; improve load, pace or transitions rather than adding rounds.',3),
 ('b1700017-0000-4000-8000-000000000017','APOLLO-W7-SUN-R1','warm_up','Run preparation','5 minutes brisk walk/easy jog before Zone 2.','none',NULL,NULL,1),
 ('b1700018-0000-4000-8000-000000000018','APOLLO-W7-SUN-R1','conditioning','Zone 2 run','85 minutes conversational Zone 2 at RPE 3-4; no fast finish.','intervals','{"work_seconds":5100,"tracking":["distance","average_pace","average_hr"],"intensity":"zone_2","fast_finish":false}'::jsonb,'Track distance, pace and HR.',2),
 ('b1700019-0000-4000-8000-000000000019','APOLLO-W7-SUN-R1','cool_down','Full Apollo mobility flow','Knee-to-wall ankle rocks 2x8/side; 90/90 hip switches 2x8/side; adductor rock-back 2x8/side; half-kneeling hip-flexor stretch with reach 45 sec/side; deep-squat pry 2x30 sec; open-book rotation 6/side; wall slide with reach 2x8; passive hang 2x30 sec.','none',NULL,NULL,3);
