DO $$
DECLARE v_existing integer; v_exact integer;
BEGIN
 SELECT count(*) INTO v_existing FROM public.performance_protocols WHERE protocol_id LIKE 'APOLLO-W7-%-R1';
 SELECT count(*) INTO v_exact FROM public.performance_protocols WHERE (protocol_id,name,authoring_scope,organisation_id,lifecycle_status) IN (
  ('APOLLO-W7-MON-R1','Apollo Strength','organisation','apollo-dogfood','draft'),('APOLLO-W7-TUE-R1','Apollo Base','organisation','apollo-dogfood','draft'),
