  ('APOLLO-W7-SUN-R1','Apollo Long','organisation','apollo-dogfood','draft'));
 IF v_existing = 7 AND v_exact = 7 THEN RETURN; END IF;
 IF v_existing <> 0 THEN RAISE EXCEPTION 'Apollo Week 7 protocol identity/content conflict'; END IF;
END $$;


